1	/** Pure replay fold and strict decoders for durable completion-standard changes. */
2	
3	import type { SessionEvent } from '@deepseek-ai/dsh-session'
4	import { GoalId } from '@deepseek-ai/dsh-goal'
5	import { CheckId, isKebabCase, StandardId, VERIFICATION_CHANGE_VERSION } from './runtime.ts'
6	import type {
7	  CertificateIsolation,
8	  CheckResult,
9	  CompletionStandardSnapshot,
10	  RelaxedCheck,
11	  StandardCheck,
12	  StandardRef,
13	  VerificationCertificate,
14	} from './types.ts'
15	import type {
16	  CertificateChangeMeta,
17	  DirectiveChangeMeta,
18	  FoldedVerification,
19	  RelaxationChangeMeta,
20	  StandardChangeMeta,
21	  StandardOperation,
22	} from './domain.ts'
23	
24	const OPERATIONS: ReadonlySet<StandardOperation> = new Set(['author', 'extend'])
25	const ISOLATIONS: ReadonlySet<CertificateIsolation> = new Set(['none', 'process', 'host'])
26	
27	/** Mutable accumulator kept private to the pure fold. */
28	export interface VerificationFoldState {
29	  standard: CompletionStandardSnapshot | undefined
30	  certificate: VerificationCertificate | undefined
31	  directivesIssued: number
32	  createdAt: number | undefined
33	  updatedAt: number | undefined
34	  lastRef: StandardRef | undefined
35	  seenStandardIds: Set<CompletionStandardSnapshot['id']>
36	}
37	
38	/**
39	 * Build an empty replay accumulator.
40	 * @returns mutable state with no current standard or prior ref.
41	 */
42	export function emptyVerificationFoldState(): VerificationFoldState {
43	  return {
44	    standard: undefined,
45	    certificate: undefined,
46	    directivesIssued: 0,
47	    createdAt: undefined,
48	    updatedAt: undefined,
49	    lastRef: undefined,
50	    seenStandardIds: new Set(),
51	  }
52	}
53	
54	// Strict per-domain decoders keep their own guards (the goal fold is the template).
55	/* jscpd:ignore-start */
56	/** Whether a value is a JSON record rather than an array. */
57	function isRecord(value: unknown): value is Record<string, unknown> {
58	  return typeof value === 'object' && value !== null && !Array.isArray(value)
59	}
60	
61	/** Require one positive safe integer. */
62	function positiveInteger(value: unknown, field: string): number {
63	  if (typeof value !== 'number' || !Number.isSafeInteger(value) || value < 1) {
64	    throw new Error(`verification change ${field} must be a positive safe integer`)
65	  }
66	  return value
67	}
68	
69	/** Require one non-negative safe integer. */
70	function nonNegativeInteger(value: unknown, field: string): number {
71	  if (typeof value !== 'number' || !Number.isSafeInteger(value) || value < 0) {
72	    throw new Error(`verification change ${field} must be a non-negative safe integer`)
73	  }
74	  return value
75	}
76	/* jscpd:ignore-end */
77	
78	/** Require one non-empty trim-normalized string. */
79	function normalizedText(value: unknown, field: string): string {
80	  if (typeof value !== 'string' || value.trim().length === 0 || value !== value.trim()) {
81	    throw new Error(`verification change ${field} must be non-empty and normalized`)
82	  }
83	  return value
84	}
85	
86	/** Require an exact sorted key set. */
87	function requireKeys(value: Record<string, unknown>, expected: readonly string[], subject: string): void {
88	  const keys = Object.keys(value).sort().join(',')
89	  const wanted = [...expected].sort().join(',')
90	  if (keys !== wanted) {
91	    throw new Error(`verification change ${subject} must have exactly ${wanted} fields`)
92	  }
93	}
94	
95	/** Decode and validate one check. */
96	function decodeCheck(value: unknown, subject: string): StandardCheck {
97	  if (!isRecord(value)) throw new Error(`verification change ${subject} must be a record`)
98	  requireKeys(value, ['id', 'outcome', 'run'], subject)
99	  const rawId = value['id']
100	  if (typeof rawId !== 'string' || !isKebabCase(rawId)) {
101	    throw new Error(`verification change ${subject}.id must be lower-kebab-case`)
102	  }
103	  return {
104	    id: CheckId(rawId),
105	    outcome: normalizedText(value['outcome'], `${subject}.outcome`),
106	    run: normalizedText(value['run'], `${subject}.run`),
107	  }
108	}
109	
110	/** Decode and validate one relaxed entry. */
111	function decodeRelaxed(value: unknown, subject: string): RelaxedCheck {
112	  if (!isRecord(value)) throw new Error(`verification change ${subject} must be a record`)
113	  requireKeys(value, ['check', 'evidence'], subject)
114	  return {
115	    check: decodeCheck(value['check'], `${subject}.check`),
116	    evidence: normalizedText(value['evidence'], `${subject}.evidence`),
117	  }
118	}
119	
120	/** Decode and validate one full standard snapshot. */
121	function decodeSnapshot(value: unknown): CompletionStandardSnapshot {
122	  if (!isRecord(value)) throw new Error('verification change standard must be a record')
123	  requireKeys(value, ['checks', 'goalId', 'id', 'relaxed', 'revision'], 'standard')
124	  if (typeof value['id'] !== 'string' || value['id'].length === 0) {
125	    throw new Error('verification change standard.id must be a non-empty string')
126	  }
127	  if (typeof value['goalId'] !== 'string' || value['goalId'].length === 0) {
128	    throw new Error('verification change standard.goalId must be a non-empty string')
129	  }
130	  if (!Array.isArray(value['checks'])) throw new Error('verification change standard.checks must be an array')
131	  if (!Array.isArray(value['relaxed'])) throw new Error('verification change standard.relaxed must be an array')
132	  const checks = value['checks'].map((check, index) => decodeCheck(check, `standard.checks[${index}]`))
133	  const relaxed = value['relaxed'].map((entry, index) => decodeRelaxed(entry, `standard.relaxed[${index}]`))
134	  const ids = new Set<string>()
135	  for (const check of checks) {
136	    if (ids.has(check.id)) throw new Error(`verification change standard.checks repeats id "${check.id}"`)
137	    ids.add(check.id)
138	  }
139	  for (const entry of relaxed) {
140	    if (ids.has(entry.check.id)) {
141	      throw new Error(`verification change standard.relaxed repeats id "${entry.check.id}"`)
142	    }
143	    ids.add(entry.check.id)
144	  }
145	  return {
146	    id: StandardId(value['id']),
147	    revision: positiveInteger(value['revision'], 'standard.revision'),
148	    goalId: GoalId(value['goalId']),
149	    checks,
150	    relaxed,
151	  }
152	}
153	
154	/** Decode and validate one standard ref. */
155	function decodeRef(value: unknown, subject: string): StandardRef {
156	  if (!isRecord(value)) throw new Error(`verification change ${subject} must be a record`)
157	  requireKeys(value, ['id', 'revision'], subject)
158	  if (typeof value['id'] !== 'string' || value['id'].length === 0) {
159	    throw new Error(`verification change ${subject}.id must be a non-empty string`)
160	  }
161	  return { id: StandardId(value['id']), revision: positiveInteger(value['revision'], `${subject}.revision`) }
162	}
163	
164	/** Decode one passing certificate result. */
165	function decodeCertificateResult(value: unknown, subject: string): CheckResult {
166	  if (!isRecord(value)) throw new Error(`verification change ${subject} must be a record`)
167	  requireKeys(value, ['checkId', 'evidence', 'status'], subject)
168	  const rawCheckId = value['checkId']
169	  if (typeof rawCheckId !== 'string' || !isKebabCase(rawCheckId)) {
170	    throw new Error(`verification change ${subject}.checkId must be lower-kebab-case`)
171	  }
172	  if (value['status'] !== 'pass') {
173	    throw new Error(`verification change ${subject}.status must be "pass" inside a certificate`)
174	  }
175	  return {
176	    checkId: CheckId(rawCheckId),
177	    status: 'pass',
178	    evidence: normalizedText(value['evidence'], `${subject}.evidence`),
179	  }
180	}
181	
182	/** Shared timestamp validation for standard-shaped changes. */
183	function decodeTimestamps(value: Record<string, unknown>): { createdAt: number; updatedAt: number } {
184	  const createdAt = nonNegativeInteger(value['createdAt'], 'createdAt')
185	  const updatedAt = nonNegativeInteger(value['updatedAt'], 'updatedAt')
186	  if (updatedAt < createdAt) throw new Error('verification change updatedAt cannot precede createdAt')
187	  return { createdAt, updatedAt }
188	}
189	
190	/** Require a self-declared payload version. */
191	function requireVersion(value: Record<string, unknown>): void {
192	  if (value['version'] !== VERIFICATION_CHANGE_VERSION) {
193	    throw new Error(`unsupported verification change version ${String(value['version'])}`)
194	  }
195	}
196	
197	/**
198	 * Decode a value that declares itself as a standard change. Unrelated values
199	 * return `undefined`; malformed standard changes fail replay loudly.
200	 * @param value - candidate durable payload.
201	 * @returns validated standard change or `undefined` for another value kind.
202	 */
203	export function decodeStandardChange(value: unknown): StandardChangeMeta | undefined {
204	  if (!isRecord(value) || value['kind'] !== 'verification/standard') return undefined
205	  requireVersion(value)
206	  requireKeys(value, ['createdAt', 'kind', 'operation', 'standard', 'updatedAt', 'version'], 'standard change')
207	  if (typeof value['operation'] !== 'string' || !OPERATIONS.has(value['operation'] as StandardOperation)) {
208	    throw new Error('verification change operation is invalid')
209	  }
210	  return {
211	    kind: 'verification/standard',
212	    version: VERIFICATION_CHANGE_VERSION,
213	    operation: value['operation'] as StandardOperation,
214	    standard: decodeSnapshot(value['standard']),
215	    ...decodeTimestamps(value),
216	  }
217	}
218	
219	/**
220	 * Decode a value that declares itself as a relaxation. Unrelated values
221	 * return `undefined`; malformed relaxations fail replay loudly.
222	 * @param value - candidate durable payload.
223	 * @returns validated relaxation or `undefined` for another value kind.
224	 */
225	export function decodeRelaxationChange(value: unknown): RelaxationChangeMeta | undefined {
226	  if (!isRecord(value) || value['kind'] !== 'verification/relaxation') return undefined
227	  requireVersion(value)
228	  requireKeys(value, ['checkId', 'createdAt', 'kind', 'standard', 'updatedAt', 'version'], 'relaxation')
229	  const rawCheckId = value['checkId']
230	  if (typeof rawCheckId !== 'string' || !isKebabCase(rawCheckId)) {
231	    throw new Error('verification change relaxation checkId must be lower-kebab-case')
232	  }
233	  const standard = decodeSnapshot(value['standard'])
234	  const last = standard.relaxed[standard.relaxed.length - 1]
235	  if (last === undefined || last.check.id !== rawCheckId) {
236	    throw new Error('verification change relaxation must end the snapshot relaxed list with its check')
237	  }
238	  return {
239	    kind: 'verification/relaxation',
240	    version: VERIFICATION_CHANGE_VERSION,
241	    checkId: CheckId(rawCheckId),
242	    standard,
243	    ...decodeTimestamps(value),
244	  }
245	}
246	
247	/**
248	 * Decode a value that declares itself as a certificate. Unrelated values
249	 * return `undefined`; malformed certificates fail replay loudly.
250	 * @param value - candidate durable payload.
251	 * @returns validated certificate or `undefined` for another value kind.
252	 */
253	export function decodeCertificateChange(value: unknown): CertificateChangeMeta | undefined {
254	  if (!isRecord(value) || value['kind'] !== 'verification/certificate') return undefined
255	  requireVersion(value)
256	  requireKeys(value, ['certificate', 'kind', 'version'], 'certificate')
257	  const certificate = value['certificate']
258	  if (!isRecord(certificate)) throw new Error('verification change certificate must be a record')
259	  requireKeys(certificate, ['goalId', 'isolation', 'recordedAt', 'results', 'standard'], 'certificate')
260	  if (typeof certificate['goalId'] !== 'string' || certificate['goalId'].length === 0) {
261	    throw new Error('verification change certificate.goalId must be a non-empty string')
262	  }
263	  if (typeof certificate['isolation'] !== 'string'
264	    || !ISOLATIONS.has(certificate['isolation'] as CertificateIsolation)) {
265	    throw new Error('verification change certificate.isolation is invalid')
266	  }
267	  if (!Array.isArray(certificate['results']) || certificate['results'].length === 0) {
268	    throw new Error('verification change certificate.results must be a non-empty array')
269	  }
270	  return {
271	    kind: 'verification/certificate',
272	    version: VERIFICATION_CHANGE_VERSION,
273	    certificate: {
274	      standard: decodeRef(certificate['standard'], 'certificate.standard'),
275	      goalId: GoalId(certificate['goalId']),
276	      isolation: certificate['isolation'] as CertificateIsolation,
277	      results: certificate['results'].map((result, index) =>
278	        decodeCertificateResult(result, `certificate.results[${index}]`)),
279	      recordedAt: nonNegativeInteger(certificate['recordedAt'], 'certificate.recordedAt'),
280	    },
281	  }
282	}
283	
284	/**
285	 * Decode a value that declares itself as a directive. Unrelated values
286	 * return `undefined`; malformed directives fail replay loudly.
287	 * @param value - candidate durable payload.
288	 * @returns validated directive or `undefined` for another value kind.
289	 */
290	export function decodeDirectiveChange(value: unknown): DirectiveChangeMeta | undefined {
291	  if (!isRecord(value) || value['kind'] !== 'verification/directive') return undefined
292	  requireVersion(value)
293	  requireKeys(value, ['detail', 'issuedAt', 'kind', 'rootCause', 'standard', 'version'], 'directive')
294	  return {
295	    kind: 'verification/directive',
296	    version: VERIFICATION_CHANGE_VERSION,
297	    standard: decodeRef(value['standard'], 'directive.standard'),
298	    rootCause: normalizedText(value['rootCause'], 'directive.rootCause'),
299	    detail: normalizedText(value['detail'], 'directive.detail'),
300	    issuedAt: nonNegativeInteger(value['issuedAt'], 'issuedAt'),
301	  }
302	}
303	
304	/** Require two checks to be identical field-for-field. */
305	function requireSameCheck(previous: StandardCheck, next: StandardCheck, subject: string): void {
306	  if (previous.id !== next.id || previous.outcome !== next.outcome || previous.run !== next.run) {
307	    throw new Error(`verification change ${subject} must preserve the existing check "${previous.id}"`)
308	  }
309	}
310	
311	/** Require the relaxed list to preserve an existing prefix exactly. */
312	function requireSameRelaxed(previous: readonly RelaxedCheck[], next: readonly RelaxedCheck[], subject: string): void {
313	  for (const [index, entry] of previous.entries()) {
314	    const candidate = next[index]
315	    if (candidate === undefined || candidate.evidence !== entry.evidence) {
316	      throw new Error(`verification change ${subject} must preserve the existing relaxation of "${entry.check.id}"`)
317	    }
318	    requireSameCheck(entry.check, candidate.check, subject)
319	  }
320	}
321	
322	/** Require one exact next revision of the current standard for the same goal. */
323	function requireNextRevision(
324	  current: CompletionStandardSnapshot,
325	  next: CompletionStandardSnapshot,
326	  operation: string,
327	): void {
328	  if (next.id !== current.id || next.revision !== current.revision + 1 || next.goalId !== current.goalId) {
329	    throw new Error(`verification ${operation} must advance the current standard by one revision for its goal`)
330	  }
331	}
332	
333	/** Require preserved creation time and monotone update time. */
334	function requireTimestampContinuity(
335	  state: VerificationFoldState,
336	  createdAt: number,
337	  updatedAt: number,
338	  operation: string,
339	): void {
340	  /* v8 ignore next -- a current standard established by this fold always has an updatedAt */
341	  if (state.updatedAt === undefined) throw new Error('current standard fold lacks updatedAt')
342	  if (createdAt !== state.createdAt || updatedAt < state.updatedAt) {
343	    throw new Error(`verification ${operation} does not preserve the current timestamps`)
344	  }
345	}
346	
347	/** Validate and apply one standard change (author or extend). */
348	function applyStandardChange(state: VerificationFoldState, change: StandardChangeMeta): void {
349	  const next = change.standard
350	  if (change.operation === 'author') {
351	    if (next.revision !== 1 || next.relaxed.length !== 0 || next.checks.length === 0
352	      || state.seenStandardIds.has(next.id)
353	      || (state.standard !== undefined && state.standard.goalId === next.goalId)) {
354	      throw new Error('verification author requires a fresh revision-one standard for a new goal')
355	    }
356	    state.seenStandardIds.add(next.id)
357	  } else {
358	    const current = state.standard
359	    if (current === undefined) throw new Error('verification extend requires a current standard')
360	    requireNextRevision(current, next, change.operation)
361	    requireTimestampContinuity(state, change.createdAt, change.updatedAt, change.operation)
362	    if (next.checks.length <= current.checks.length) {
363	      throw new Error('verification extend must add at least one check')
364	    }
365	    for (const [index, check] of current.checks.entries()) {
366	      requireSameCheck(check, next.checks[index] as StandardCheck, change.operation)
367	    }
368	    if (next.relaxed.length !== current.relaxed.length) {
369	      throw new Error('verification extend cannot change relaxations')
370	    }
371	    requireSameRelaxed(current.relaxed, next.relaxed, change.operation)
372	  }
373	  state.standard = next
374	  state.certificate = undefined
375	  state.createdAt = change.createdAt
376	  state.updatedAt = change.updatedAt
377	  state.lastRef = { id: next.id, revision: next.revision }
378	}
379	
380	/** Validate and apply one relaxation. */
381	function applyRelaxationChange(state: VerificationFoldState, change: RelaxationChangeMeta): void {
382	  const current = state.standard
383	  if (current === undefined) throw new Error('verification relaxation requires a current standard')
384	  const next = change.standard
385	  requireNextRevision(current, next, 'relaxation')
386	  requireTimestampContinuity(state, change.createdAt, change.updatedAt, 'relaxation')
387	  const removed = current.checks.find(check => check.id === change.checkId)
388	  if (removed === undefined) {
389	    throw new Error(`verification relaxation names unknown check "${change.checkId}"`)
390	  }
391	  const remaining = current.checks.filter(check => check.id !== change.checkId)
392	  if (next.checks.length !== remaining.length) {
393	    throw new Error('verification relaxation must remove exactly its named check')
394	  }
395	  for (const [index, check] of remaining.entries()) {
396	    requireSameCheck(check, next.checks[index] as StandardCheck, 'relaxation')
397	  }
398	  if (next.relaxed.length !== current.relaxed.length + 1) {
399	    throw new Error('verification relaxation must append exactly one relaxed entry')
400	  }
401	  requireSameRelaxed(current.relaxed, next.relaxed, 'relaxation')
402	  const appended = next.relaxed[next.relaxed.length - 1] as RelaxedCheck
403	  requireSameCheck(removed, appended.check, 'relaxation')
404	  state.standard = next
405	  state.certificate = undefined
406	  state.createdAt = change.createdAt
407	  state.updatedAt = change.updatedAt
408	  state.lastRef = { id: next.id, revision: next.revision }
409	}
410	
411	/** Validate and apply one certificate. */
412	function applyCertificateChange(state: VerificationFoldState, change: CertificateChangeMeta): void {
413	  const current = state.standard
414	  if (current === undefined) throw new Error('verification certificate requires a current standard')
415	  const certificate = change.certificate
416	  if (certificate.standard.id !== current.id || certificate.standard.revision !== current.revision
417	    || certificate.goalId !== current.goalId) {
418	    throw new Error('verification certificate must cover the exact current standard revision')
419	  }
420	  if (certificate.results.length !== current.checks.length) {
421	    throw new Error('verification certificate must carry one result per active check')
422	  }
423	  for (const [index, check] of current.checks.entries()) {
424	    if (certificate.results[index]?.checkId !== check.id) {
425	      throw new Error(`verification certificate result ${index} must answer check "${check.id}"`)
426	    }
427	  }
428	  /* v8 ignore next -- a current standard established by this fold always has an updatedAt */
429	  if (state.updatedAt === undefined) throw new Error('current standard fold lacks updatedAt')
430	  if (certificate.recordedAt < state.updatedAt) {
431	    throw new Error('verification certificate cannot precede the current standard update')
432	  }
433	  state.certificate = certificate
434	}
435	
436	/** Validate and apply one directive record. */
437	function applyDirectiveChange(state: VerificationFoldState, change: DirectiveChangeMeta): void {
438	  const current = state.standard
439	  if (current === undefined) throw new Error('verification directive requires a current standard')
440	  if (change.standard.id !== current.id || change.standard.revision !== current.revision) {
441	    throw new Error('verification directive must reference the exact current standard revision')
442	  }
443	  /* v8 ignore next -- a current standard established by this fold always has a createdAt */
444	  if (state.createdAt === undefined) throw new Error('current standard fold lacks createdAt')
445	  if (change.issuedAt < state.createdAt) {
446	    throw new Error('verification directive cannot precede the current standard creation')
447	  }
448	  state.directivesIssued += 1
449	}
450	
451	/**
452	 * Apply one session event to the strict durable completion-standard fold.
453	 * @param state - mutable fold accumulator.
454	 * @param event - next event in sequence order.
455	 */
456	export function applyVerificationEvent(state: VerificationFoldState, event: SessionEvent): void {
457	  switch (event.type) {
458	    case 'verification/standard': {
459	      const change = decodeStandardChange(event.data)
460	      /* v8 ignore next -- the event's declared payload always identifies itself as a standard change */
461	      if (change === undefined) throw new Error(`verification change at session event ${event.seq} has an invalid kind`)
462	      applyStandardChange(state, change)
463	      return
464	    }
465	    case 'verification/relaxation': {
466	      const change = decodeRelaxationChange(event.data)
467	      /* v8 ignore next -- the event's declared payload always identifies itself as a relaxation */
468	      if (change === undefined) throw new Error(`verification change at session event ${event.seq} has an invalid kind`)
469	      applyRelaxationChange(state, change)
470	      return
471	    }
472	    case 'verification/certificate': {
473	      const change = decodeCertificateChange(event.data)
474	      /* v8 ignore next -- the event's declared payload always identifies itself as a certificate */
475	      if (change === undefined) throw new Error(`verification change at session event ${event.seq} has an invalid kind`)
476	      applyCertificateChange(state, change)
477	      return
478	    }
479	    case 'verification/directive': {
480	      const change = decodeDirectiveChange(event.data)
481	      /* v8 ignore next -- the event's declared payload always identifies itself as a directive */
482	      if (change === undefined) throw new Error(`verification change at session event ${event.seq} has an invalid kind`)
483	      applyDirectiveChange(state, change)
484	      return
485	    }
486	    default:
487	      // Non-verification events do not affect the completion-standard fold.
488	  }
489	}
490	
491	/**
492	 * Fold current completion-standard state from a contiguous session event log.
493	 * @param events - session events in sequence order.
494	 * @returns a fresh durable projection.
495	 */
496	export function foldVerification(events: readonly SessionEvent[]): FoldedVerification {
497	  const state = emptyVerificationFoldState()
498	  for (const event of events) applyVerificationEvent(state, event)
499	  return {
500	    ...state.standard === undefined ? {} : { standard: state.standard },
501	    ...state.certificate === undefined ? {} : { certificate: state.certificate },
502	    directivesIssued: state.directivesIssued,
503	    ...state.createdAt === undefined ? {} : { createdAt: state.createdAt },
504	    ...state.updatedAt === undefined ? {} : { updatedAt: state.updatedAt },
505	    ...state.lastRef === undefined ? {} : { lastRef: { ...state.lastRef } },
506	  }
507	}
508

